r.post('/reconcile',async(req,res,next)=>{const p=reconcileSchema.safeParse(req.body);if(!p.success)return fail(res,400,'VALIDATION_ERROR','Choose a valid shift date.');try{const a=await checked(req,res,p.data.stationId,true);if(!a)return;const [{data:readings,error:re},{data:kgReadings,error:kre}]=await Promise.all([req.supabase.from('nozzle_meter_readings').select('id,expected_amount').eq('station_id',p.data.stationId).eq('shift_date',p.data.shiftDate).eq('status','approved'),req.supabase.from('kg_nozzle_meter_readings').select('id,expected_amount').eq('station_id',p.data.stationId).eq('shift_date',p.data.shiftDate).eq('status','approved')]);if(re)throw re;if(kre)throw kre;const readingIds=new Set((readings||[]).map(x=>x.id));const kgReadingIds=new Set((kgReadings||[]).map(x=>x.id));let collections=[];let reversals=[];let kgCollections=[];let kgReversals=[];if(readingIds.size){const {data,error:ce}=await req.supabase.from('sales_collections').select('id,amount,reading_id').eq('station_id',p.data.stationId).in('reading_id',[...readingIds]);if(ce)throw ce;collections=data||[];const collectionIds=collections.map(x=>x.id);if(collectionIds.length){const {data,error:rvError}=await req.supabase.from('sales_collection_reversals').select('collection_id,amount').eq('station_id',p.data.stationId).in('collection_id',collectionIds);if(rvError)throw rvError;reversals=data||[]}}if(kgReadingIds.size){const {data:kgCollectionsData,error:kgce}=await req.supabase.from('kg_sales_collections').select('id,amount,reading_id').eq('station_id',p.data.stationId).in('reading_id',[...kgReadingIds]);if(kgce)throw kgce;kgCollections=kgCollectionsData||[];const kgCollectionIds=kgCollections.map(x=>x.id);if(kgCollectionIds.length){const {data:kgRv,error:kgRvError}=await req.supabase.from('kg_sales_collection_reversals').select('collection_id,amount').eq('station_id',p.data.stationId).in('collection_id',kgCollectionIds);if(kgRvError)throw kgRvError;kgReversals=kgRv||[]}}const reversedByCollection=new Map();for(const rv of reversals)reversedByCollection.set(rv.collection_id,(reversedByCollection.get(rv.collection_id)||0)+Number(rv.amount));const expected=(readings||[]).reduce((s,x)=>s+Number(x.expected_amount),0)+(kgReadings||[]).reduce((s,x)=>s+Number(x.expected_amount),0);const kgReversedByCollection=new Map();for(const rv of kgReversals)kgReversedByCollection.set(rv.collection_id,(kgReversedByCollection.get(rv.collection_id)||0)+Number(rv.amount));const collected=collections.reduce((s,x)=>s+Number(x.amount)-(reversedByCollection.get(x.id)||0),0)+kgCollections.reduce((s,x)=>s+Number(x.amount)-(kgReversedByCollection.get(x.id)||0),0);const variance=Number((collected-expected).toFixed(2));const status=Math.abs(variance)<0.01?'balanced':variance<0?'short':'over';const q=await req.supabase.from('shift_reconciliations').upsert({station_id:p.data.stationId,shift_date:p.data.shiftDate,expected_amount:expected,collected_amount:collected,variance_amount:variance,status,notes:p.data.notes||null,reconciled_by:req.user.id,reconciled_at:new Date().toISOString()},{onConflict:'station_id,shift_date'}).select('*').single();if(q.error)throw q.error;await audit(req,a,'SHIFT_RECONCILED','shift_reconciliation',q.data.id,{expected,collected,variance,status});res.json({data:q.data})}catch(e){routeError(next,e)}});
 r.get('/shift-openings/roster',async(req,res,next)=>{const p=z.object({stationId:uuid,cashShiftId:uuid}).safeParse({stationId:req.query.stationId,cashShiftId:req.query.cashShiftId});if(!p.success)return fail(res,400,'VALIDATION_ERROR','Select a valid station and shift.');try{const a=await checked(req,res,p.data.stationId);if(!a)return;const {data:shift,error:se}=await req.supabase.from('station_cash_shifts').select('id,status,cashier_user_id').eq('id',p.data.cashShiftId).eq('station_id',p.data.stationId).maybeSingle();if(se)throw se;if(!shift)return fail(res,404,'SHIFT_NOT_FOUND','Shift not found in this branch.');if(!a.canManage&&shift.cashier_user_id!==req.user.id)return fail(res,403,'SHIFT_NOT_ASSIGNED','You can only view your own shift roster.');const [{data:roster,error:re},{data:openings,error:oe},{data:nozzles,error:ne}]=await Promise.all([req.supabase.from('shift_nozzle_roster').select('nozzle_id,assigned_at,assigned_by').eq('station_id',p.data.stationId).eq('cash_shift_id',p.data.cashShiftId),req.supabase.from('shift_meter_openings').select('nozzle_id,status,unit_of_measure,opening_meter').eq('station_id',p.data.stationId).eq('cash_shift_id',p.data.cashShiftId),req.supabase.from('pump_nozzles').select('id,name,status,tank_id,station_tanks(unit_of_measure)').eq('station_id',p.data.stationId).eq('status','active')]);if(re)throw re;if(oe)throw oe;if(ne)throw ne;const assigned=roster||[], approved=(openings||[]).filter(x=>x.status==='approved');const items=assigned.map(x=>{const n=(nozzles||[]).find(y=>y.id===x.nozzle_id);const candidates=(openings||[]).filter(y=>y.nozzle_id===x.nozzle_id);const o=approved.find(y=>y.nozzle_id===x.nozzle_id);const openingStatus=o?'approved':candidates.some(y=>y.status==='pending')?'pending':candidates.some(y=>y.status==='rejected')?'rejected':'missing';return {nozzleId:x.nozzle_id,nozzleName:n?.name||x.nozzle_id,unit:o?.unit_of_measure||n?.station_tanks?.unit_of_measure||'litre',openingStatus,openingMeter:o?.opening_meter??null}});res.json({data:{cashShiftId:p.data.cashShiftId,configured:assigned.length>0,ready:assigned.length>0&&items.every(x=>x.openingStatus==='approved'),expectedCount:assigned.length,approvedCount:items.filter(x=>x.openingStatus==='approved').length,items}})}catch(e){routeError(next,e)}});
 r.post('/shift-openings/roster',async(req,res,next)=>{const p=z.object({stationId:uuid,cashShiftId:uuid,nozzleIds:z.array(uuid).min(1).max(100)}).safeParse(req.body);if(!p.success)return fail(res,400,'VALIDATION_ERROR','Select an open shift and at least one nozzle expected to operate.');try{const a=await checked(req,res,p.data.stationId,true);if(!a)return;const result=await req.supabase.rpc('set_shift_nozzle_roster',{p_station_id:p.data.stationId,p_shift_id:p.data.cashShiftId,p_nozzle_ids:p.data.nozzleIds,p_assigned_by:req.user.id});if(result.error){const m=String(result.error.message||'');if(m.includes('OPEN_CASH_SHIFT_REQUIRED'))return fail(res,409,'OPEN_CASH_SHIFT_REQUIRED','Choose an open cashier shift.');if(m.includes('ROSTER_LOCKED_AFTER_ACTIVITY'))return fail(res,409,'ROSTER_LOCKED_AFTER_ACTIVITY','The shift roster cannot change after opening readings or sales activity have started.');if(m.includes('EMPTY_SHIFT_NOZZLE_ROSTER'))return fail(res,400,'EMPTY_SHIFT_NOZZLE_ROSTER','Assign at least one nozzle to the shift.');if(m.includes('INVALID_SHIFT_NOZZLE'))return fail(res,400,'INVALID_SHIFT_NOZZLE','Only active nozzles from this branch can be assigned.');throw result.error}await audit(req,a,'SHIFT_NOZZLE_ROSTER_CONFIGURED','shift_nozzle_roster',p.data.cashShiftId,{nozzleIds:p.data.nozzleIds});res.json({data:result.data})}catch(e){routeError(next,e)}});
