 r.post('/shift-openings',async(req,res,next)=>{const p=z.object({stationId:uuid,cashShiftId:uuid,nozzleId:uuid,unit:z.enum(['litre','kg']),openingMeter:z.coerce.number().min(0).max(100000000),notes:z.string().max(1000).optional()}).safeParse(req.body);if(!p.success)return fail(res,400,'VALIDATION_ERROR','Provide the open shift, nozzle, unit and opening meter.');try{const a=await checked(req,res,p.data.stationId);if(!a)return;const {data:shift,error:se}=await req.supabase.from('station_cash_shifts').select('id,cashier_user_id,status').eq('id',p.data.cashShiftId).eq('station_id',p.data.stationId).maybeSingle();if(se)throw se;if(!shift||shift.status!=='open')return fail(res,409,'OPEN_CASH_SHIFT_REQUIRED','Choose an open cashier shift.');if(!a.canManage&&shift.cashier_user_id!==req.user.id)return fail(res,403,'SHIFT_NOT_ASSIGNED','Attendants can only submit opening readings for their own shift.');const {data:nozzle,error:ne}=await req.supabase.from('pump_nozzles').select('id,name,status,tank_id,station_tanks(unit_of_measure)').eq('id',p.data.nozzleId).eq('station_id',p.data.stationId).maybeSingle();if(ne)throw ne;if(!nozzle||nozzle.status!=='active')return fail(res,404,'ACTIVE_NOZZLE_NOT_FOUND','Choose an active nozzle in this branch.');const unit=nozzle.station_tanks?.unit_of_measure||'litre';if(unit!==p.data.unit)return fail(res,409,'FUEL_UNIT_MISMATCH','The meter unit must match the nozzle tank unit.');const {data:rosterItem,error:ri}=await req.supabase.from('shift_nozzle_roster').select('nozzle_id').eq('station_id',p.data.stationId).eq('cash_shift_id',p.data.cashShiftId).eq('nozzle_id',p.data.nozzleId).maybeSingle();if(ri)throw ri;if(!rosterItem)return fail(res,409,'NOZZLE_NOT_ASSIGNED_TO_SHIFT','A manager must assign this nozzle to the shift roster before its opening meter can be submitted.');const {data:existing,error:xe}=await req.supabase.from('shift_meter_openings').select('id,status').eq('cash_shift_id',p.data.cashShiftId).eq('nozzle_id',p.data.nozzleId).in('status',['pending','approved']).maybeSingle();if(xe)throw xe;if(existing)return fail(res,409,'OPENING_ALREADY_SUBMITTED','An opening reading is already pending or approved for this nozzle and shift.');const {data:row,error:ie}=await req.supabase.from('shift_meter_openings').insert({station_id:p.data.stationId,cash_shift_id:p.data.cashShiftId,nozzle_id:p.data.nozzleId,unit_of_measure:p.data.unit,opening_meter:p.data.openingMeter,submitted_by:req.user.id,submission_notes:p.data.notes||null}).select('*').single();if(ie){if(String(ie.message||'').includes('one_active_shift_opening_per_nozzle'))return fail(res,409,'OPENING_ALREADY_SUBMITTED','An opening reading is already pending or approved for this nozzle and shift.');throw ie}await audit(req,a,'SHIFT_OPENING_METER_SUBMITTED','shift_meter_opening',row.id,{cashShiftId:shift.id,nozzleId:nozzle.id,unit:p.data.unit});res.status(201).json({data:row})}catch(e){routeError(next,e)}});
