async function audit(req,a,action,type,id,metadata={}){const {error}=await req.supabase.from('audit_events').insert({company_id:a.station.company_id,station_id:a.station.id,actor_user_id:req.user.id,action,entity_type:type,entity_id:String(id),metadata});if(error)throw error}
